-- TARIFF — docs/DESIGN-UPDATE-2026-10-04.md §5
-- ===========================================================================
--
-- Two new tables and one enum: a price book of local charges at a POL
-- (sheet `Tarrif`, Purchase → Price List).
--
--   tariff        Country · POL · Movement Type · Tariff Type
--   tariff_line   Cost Head · Container Size · Unit · Unit Price · Currency
--
-- tariff_type is an enum of the two values the sheet names (H5). Nothing
-- existing is altered. The DDL was generated by `prisma migrate diff`; the
-- integrity, tenancy, guard and audit statements below it are hand-written.
-- ===========================================================================

-- CreateEnum
CREATE TYPE "tariff_type" AS ENUM ('PORT_TARIFF', 'CFS_CHARGE');

-- CreateTable
CREATE TABLE "tariff" (
    "tenant_id" BIGINT NOT NULL,
    "id" BIGSERIAL NOT NULL,
    "code" VARCHAR(32) NOT NULL,
    "country" VARCHAR(100) NOT NULL,
    "pol_id" BIGINT NOT NULL,
    "movement_type" "movement_type" NOT NULL,
    "tariff_type" "tariff_type" NOT NULL,
    "is_active" BOOLEAN NOT NULL DEFAULT true,
    "created_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updated_at" TIMESTAMPTZ(6) NOT NULL,
    "created_by" BIGINT,
    "updated_by" BIGINT,
    "deleted_at" TIMESTAMPTZ(6),

    CONSTRAINT "tariff_pkey" PRIMARY KEY ("id")
);

-- CreateTable
CREATE TABLE "tariff_line" (
    "tenant_id" BIGINT NOT NULL,
    "id" BIGSERIAL NOT NULL,
    "tariff_id" BIGINT NOT NULL,
    "sort_order" INTEGER NOT NULL DEFAULT 0,
    "cost_head_id" BIGINT NOT NULL,
    "container_size_id" BIGINT,
    "cost_unit_id" BIGINT NOT NULL,
    "unit_price" DECIMAL(18,4) NOT NULL,
    "currency_id" BIGINT NOT NULL,
    "is_active" BOOLEAN NOT NULL DEFAULT true,
    "created_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updated_at" TIMESTAMPTZ(6) NOT NULL,
    "created_by" BIGINT,
    "updated_by" BIGINT,
    "deleted_at" TIMESTAMPTZ(6),

    CONSTRAINT "tariff_line_pkey" PRIMARY KEY ("id")
);

