-- ---------------------------------------------------------------- integrity
ALTER TABLE "tariff_line" ADD CONSTRAINT "tariff_line_price_not_negative"
  CHECK ("unit_price" >= 0);

-- ------------------------------------------------------------------ tenancy
ALTER TABLE "tariff" ENABLE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON "tariff"
  USING (tenant_id = app_staff_tenant())
  WITH CHECK (tenant_id = app_staff_tenant());

ALTER TABLE "tariff_line" ENABLE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON "tariff_line"
  USING (tenant_id = app_staff_tenant())
  WITH CHECK (tenant_id = app_staff_tenant());

GRANT SELECT, INSERT, UPDATE ON TABLE "tariff" TO ff_app;
GRANT USAGE, SELECT ON SEQUENCE "tariff_id_seq" TO ff_app;
GRANT SELECT, INSERT, UPDATE ON TABLE "tariff_line" TO ff_app;
GRANT USAGE, SELECT ON SEQUENCE "tariff_line_id_seq" TO ff_app;

CREATE TRIGGER "tariff_audit"
  AFTER INSERT OR UPDATE OR DELETE ON "tariff"
  FOR EACH ROW EXECUTE FUNCTION app_audit_row();
CREATE TRIGGER "tariff_line_audit"
  AFTER INSERT OR UPDATE OR DELETE ON "tariff_line"
  FOR EACH ROW EXECUTE FUNCTION app_audit_row();

-- §4 rule 10. Port, container size, unit and currency are system-capable and
-- reached by a single-column key, so the constraint alone cannot say whose row
-- it is; the guard refuses another workspace's private one.
CREATE TRIGGER tariff_pol_id_tenant_guard
  BEFORE INSERT OR UPDATE OF pol_id ON tariff
  FOR EACH ROW EXECUTE FUNCTION app_assert_parent_tenant('port', 'pol_id');
CREATE TRIGGER tariff_line_container_size_id_tenant_guard
  BEFORE INSERT OR UPDATE OF container_size_id ON tariff_line
  FOR EACH ROW EXECUTE FUNCTION app_assert_parent_tenant('container_size', 'container_size_id');
CREATE TRIGGER tariff_line_cost_unit_id_tenant_guard
  BEFORE INSERT OR UPDATE OF cost_unit_id ON tariff_line
  FOR EACH ROW EXECUTE FUNCTION app_assert_parent_tenant('cost_unit', 'cost_unit_id');
CREATE TRIGGER tariff_line_currency_id_tenant_guard
  BEFORE INSERT OR UPDATE OF currency_id ON tariff_line
  FOR EACH ROW EXECUTE FUNCTION app_assert_parent_tenant('currency', 'currency_id');
